using System;using System.IO;using System.Reflection;using UnityEngine;using Bokumyaku.Presentation;
public static class InkResetReuseCheck {
 public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(g==null||!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");if(g.ResumeAvailable)g.AbandonRun();if(!g.TryStartRun(42))throw new Exception("Start failed");g.SetPaused(true);g.PresentBattle();var texture=g.BranchOverlay;int initializations=g.InkFullInitializations;var flags=BindingFlags.Instance|BindingFlags.NonPublic;var world=typeof(BokumyakuGame).GetField("battleWorld",flags).GetValue(g);var upper=(SpriteRenderer)world.GetType().GetField("upperInk",flags).GetValue(world);var lower=(SpriteRenderer)world.GetType().GetField("lowerInk",flags).GetValue(world);var upperSprite=upper.sprite;var lowerSprite=lower.sprite;
 for(int i=0;i<3;i++){if(!g.AbandonRun()||!g.TryStartRun(43+i))throw new Exception("Restart failed");g.SetPaused(true);g.PresentBattle();if(g.BranchOverlay!=texture||g.InkFullInitializations!=initializations||upper.sprite!=upperSprite||lower.sprite!=lowerSprite)throw new Exception("GPU resource churn");if(g.Run.TickCount!=0)throw new Exception("Unexpected simulation tick");}
 var r=new{passed=true,restarts=3,textureIdentityPreserved=true,inkSpriteIdentitiesPreserved=true,fullInitializations=initializations,method="Abandon/start through real game APIs in isolated paused Play"};File.WriteAllText(Path.GetFullPath("../docs/evidence/ink-reset-reuse-play.json"),Newtonsoft.Json.JsonConvert.SerializeObject(r));return r;
 }
